import type { DraftModel } from './draft';
// One model per map, generated by scripts/train-draft.ts. Do not edit the JSON by hand.
import meadow from './models/meadow.json';
import river from './models/river.json';

export const DRAFT_MODELS: Record<string, DraftModel> = { meadow, river };

/** The draft model for `mapId`, falling back to the first map's model if that map has none yet. */
export function draftModelFor(mapId: string): DraftModel {
  const m = DRAFT_MODELS[mapId];
  return m && m.games > 0 ? m : DRAFT_MODELS.meadow;
}
